    def test_loop(self):
        self.assertEqual(render_message('Bo', 'report.j2'), 'Report for Bo\nItem 1: 1\nItem 2: 4\nItem 3: 9\n')
    def test_filter(self):
        self.assertEqual(render_message('Bo', 'welcome.j2'), 'Welcome BO!\n')
