        self.assertEqual(render_message('{{ 7 * 7 }}', 'notice.j2'), 'To: {{ 7 * 7 }}\nYour total is 42.\nSent with NotifyHub\n')
    def test_manifest_templates_render(self):
        for name in json.loads((TEMPLATE_DIR / 'manifest.json').read_text(encoding='utf-8')):
            rendered = render_message('Dana', name)
            self.assertIsInstance(rendered, str)
            self.assertTrue(rendered.endswith('\n'), name)
    def test_missing_template(self):
        self.assertRaises(TemplateNotFound, render_message, 'Dana', 'nope.j2')
    def test_directory_traversal_rejected(self):
        for name in ('../README.md', '../app/render.py', '/etc/passwd'):
